let _markdown = "\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nimport { WidthTrigger } from './theme.client';\n\nOverview [#overview]\n\n<FeedbackBlock id=\"c8fb674cec5a4b8a\" body=\"Fumadocs UI adds its own colors, animations, and utilities with Tailwind CSS preset.\">\n  Fumadocs UI adds its own colors, animations, and utilities with Tailwind CSS preset.\n</FeedbackBlock>\n\nSetup [#setup]\n\n<FeedbackBlock id=\"701ea9b84b622db0\" body=\"Only Tailwind CSS v4 is supported, the preset will also include source to Fumadocs UI itself:\">\n  Only Tailwind CSS v4 is supported, the preset will also include source to Fumadocs UI itself:\n</FeedbackBlock>\n\n```css title=\"Tailwind CSS\"\n@import 'tailwindcss';\n@import 'fumadocs-ui/css/neutral.css';\n@import 'fumadocs-ui/css/preset.css';\n```\n\n<FeedbackBlock id=\"4448b2f39d5a16af\" body=\"For Shadcn UI, you can use the shadcn preset instead. Fumadocs UI will adopt colors from your Shadcn UI theme.\">\n  For **Shadcn UI**, you can use the `shadcn` preset instead. Fumadocs UI will adopt colors from your Shadcn UI theme.\n</FeedbackBlock>\n\n```css\n@import 'tailwindcss';\n@import 'fumadocs-ui/css/shadcn.css';\n@import 'fumadocs-ui/css/preset.css';\n```\n\n<FeedbackBlock id=\"451825f43dc59e4a\" body=\"See Colors for details.\">\n  See [Colors](#colors) for details.\n</FeedbackBlock>\n\nPreflight Changes [#preflight-changes]\n\n<FeedbackBlock\n  id=\"2f877f8332847abe\"\n  body=\"By using the Tailwind CSS plugin, or the pre-built stylesheet, your default border, text and background\ncolors will be changed.\"\n>\n  By using the Tailwind CSS plugin, or the pre-built stylesheet, your default border, text and background\n  colors will be changed.\n</FeedbackBlock>\n\nLight/Dark Modes [#lightdark-modes]\n\n<FeedbackBlock id=\"ecb8c24af7d1dd9c\" body=\"Fumadocs supports light/dark modes with next-themes, it is included in Root Provider.\">\n  Fumadocs supports light/dark modes with [`next-themes`](https://github.com/pacocoursey/next-themes), it is included in Root Provider.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"dfd648d0d7201671\" body=\"See Root Provider to learn more.\">\n  See [Root Provider](/docs/ui/layouts/root-provider#theme-provider) to learn more.\n</FeedbackBlock>\n\nRTL Layout [#rtl-layout]\n\n<FeedbackBlock id=\"ab3a09dbf7e58623\" body=\"RTL (Right-to-left) layout is supported.\">\n  RTL (Right-to-left) layout is supported.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"6bf788bfc25ac25a\" body=\"To enable RTL, set the dir prop to rtl in body and root provider.\">\n  To enable RTL, set the `dir` prop to `rtl` in body and root provider.\n</FeedbackBlock>\n\n```tsx\nimport { RootProvider } from 'fumadocs-ui/provider/<framework>';\nimport type { ReactNode } from 'react';\n\nexport default function RootLayout({ children }: { children: ReactNode }) {\n  return (\n    <html lang=\"en\" suppressHydrationWarning>\n      <body dir=\"rtl\">\n        <RootProvider dir=\"rtl\">{children}</RootProvider>\n      </body>\n    </html>\n  );\n}\n```\n\nLayout Width [#layout-width]\n\n<FeedbackBlock id=\"7e9db39881f29c06\" body=\"Customise the max width of docs layout with CSS Variables.\">\n  Customise the max width of docs layout with CSS Variables.\n</FeedbackBlock>\n\n```css\n:root {\n  --fd-layout-width: 1400px;\n}\n```\n\n<WidthTrigger />\n\nColors [#colors]\n\n<FeedbackBlock id=\"82cf90ba13e5b144\" body=\"It comes with many presets out-of-the-box, you can pick one you prefer.\">\n  It comes with many presets out-of-the-box, you can pick one you prefer.\n</FeedbackBlock>\n\n```css\n@import 'fumadocs-ui/css/<theme>.css';\n@import 'fumadocs-ui/css/preset.css';\n```\n\n<Tabs items={['neutral', 'black', 'vitepress', 'dusk', 'catppuccin', 'ocean', 'purple', 'solar', 'emerald', 'ruby', 'aspen']}>\n  <Tab value=\"neutral\">\n        <img alt=\"Neutral\" src={__img0} placeholder=\"blur\" />\n  </Tab>\n\n  <Tab value=\"black\">\n        <img alt=\"Black\" src={__img1} placeholder=\"blur\" />\n  </Tab>\n\n  <Tab value=\"vitepress\">\n        <img alt=\"Vitepress\" src={__img2} placeholder=\"blur\" />\n  </Tab>\n\n  <Tab value=\"dusk\">\n        <img alt=\"Dusk\" src={__img3} placeholder=\"blur\" />\n  </Tab>\n\n  <Tab value=\"Catppuccin\">\n        <img alt=\"Catppuccin\" src={__img4} placeholder=\"blur\" />\n  </Tab>\n\n  <Tab value=\"ocean\">\n        <img alt=\"Ocean\" src={__img5} placeholder=\"blur\" />\n  </Tab>\n\n  <Tab value=\"purple\">\n        <img alt=\"Purple\" src={__img6} placeholder=\"blur\" />\n  </Tab>\n\n  <Tab value=\"solar\">\n        <img alt=\"Solar\" src={__img7} placeholder=\"blur\" />\n  </Tab>\n\n  <Tab value=\"emerald\">\n        <img alt=\"Emerald\" src={__img8} placeholder=\"blur\" />\n  </Tab>\n\n  <Tab value=\"ruby\">\n        <img alt=\"Ruby\" src={__img9} placeholder=\"blur\" />\n  </Tab>\n\n  <Tab value=\"aspen\">\n        <img alt=\"Aspen\" src={__img10} placeholder=\"blur\" />\n  </Tab>\n</Tabs>\n\n<FeedbackBlock id=\"16571045100dc10a\" body=\"The design system was inspired by Shadcn UI, you can also customize the colors using CSS/Theme variables.\">\n  The design system was inspired by [Shadcn UI](https://ui.shadcn.com), you can also customize the colors using [CSS/Theme variables](https://tailwindcss.com/docs/theme).\n</FeedbackBlock>\n\n```css title=\"global.css\"\n@theme {\n  --color-fd-background: hsl(0, 0%, 96%);\n  --color-fd-foreground: hsl(0, 0%, 3.9%);\n  --color-fd-muted: hsl(0, 0%, 96.1%);\n  --color-fd-muted-foreground: hsl(0, 0%, 45.1%);\n  --color-fd-popover: hsl(0, 0%, 98%);\n  --color-fd-popover-foreground: hsl(0, 0%, 15.1%);\n  --color-fd-card: hsl(0, 0%, 94.7%);\n  --color-fd-card-foreground: hsl(0, 0%, 3.9%);\n  --color-fd-border: hsla(0, 0%, 80%, 50%);\n  --color-fd-primary: hsl(0, 0%, 9%);\n  --color-fd-primary-foreground: hsl(0, 0%, 98%);\n  --color-fd-secondary: hsl(0, 0%, 93.1%);\n  --color-fd-secondary-foreground: hsl(0, 0%, 9%);\n  --color-fd-accent: hsla(0, 0%, 82%, 50%);\n  --color-fd-accent-foreground: hsl(0, 0%, 9%);\n  --color-fd-ring: hsl(0, 0%, 63.9%);\n}\n\n.dark {\n  --color-fd-background: hsl(0, 0%, 7.04%);\n  --color-fd-foreground: hsl(0, 0%, 92%);\n  --color-fd-muted: hsl(0, 0%, 12.9%);\n  --color-fd-muted-foreground: hsla(0, 0%, 70%, 0.8);\n  --color-fd-popover: hsl(0, 0%, 11.6%);\n  --color-fd-popover-foreground: hsl(0, 0%, 86.9%);\n  --color-fd-card: hsl(0, 0%, 9.8%);\n  --color-fd-card-foreground: hsl(0, 0%, 98%);\n  --color-fd-border: hsla(0, 0%, 40%, 20%);\n  --color-fd-primary: hsl(0, 0%, 98%);\n  --color-fd-primary-foreground: hsl(0, 0%, 9%);\n  --color-fd-secondary: hsl(0, 0%, 12.9%);\n  --color-fd-secondary-foreground: hsl(0, 0%, 92%);\n  --color-fd-accent: hsla(0, 0%, 40.9%, 30%);\n  --color-fd-accent-foreground: hsl(0, 0%, 90%);\n  --color-fd-ring: hsl(0, 0%, 54.9%);\n}\n```\n\nTypography [#typography]\n\n<FeedbackBlock id=\"29835f152ca8f717\" body=\"We have a built-in plugin forked from Tailwind CSS Typography.\">\n  We have a built-in plugin forked from [Tailwind CSS Typography](https://tailwindcss.com/docs/typography-plugin).\n</FeedbackBlock>\n\n<FeedbackBlock id=\"a4ffc71d0f4c28c9\" body=\"The plugin adds a prose class and variants to customise it.\">\n  The plugin adds a `prose` class and variants to customise it.\n</FeedbackBlock>\n\n```tsx\n<div className=\"prose\">\n  <h1>Good Heading</h1>\n</div>\n```\n\n> <FeedbackBlock id=\"9fe4421cb641c8cb\" body=\"The plugin is supposed to work with Fumadocs UI's MDX components, it may conflict with @tailwindcss/typography.\">\n>   The plugin is supposed to work with Fumadocs UI's MDX components, it may conflict with `@tailwindcss/typography`.\n> </FeedbackBlock>\n>\n> <FeedbackBlock id=\"8340e959930dc074\" body=\"If you need to use @tailwindcss/typography over the default plugin, set a className option to avoid conflicts.\">\n>   If you need to use `@tailwindcss/typography` over the default plugin, [set a `className` option](https://github.com/tailwindlabs/tailwindcss-typography/blob/main/README.md#changing-the-default-class-name) to avoid conflicts.\n> </FeedbackBlock>\n>\n> ```sass\n> @import 'tailwindcss';\n> @plugin \"@tailwindcss/typography\" {\n>   className: wysiwyg;\n> }\n> ```\n";
